from itertools import product

def find_magic_sequence(length, fixed_assignments):
    for seq in product(range(length + 1), repeat=length):
        if all(seq[i] == seq.count(i) for i in range(length)):
            if all(seq[i] == fixed_assignments.get(i, None) for i in fixed_assignments):
                return list(seq)
    return None

fixed_assignments = {11: 0, 12: 0}
result = find_magic_sequence(14, fixed_assignments)
if result is not None:
    print(result)
else:
    print("UNSATISFIABLE")
